<?php defined('BASEPATH') OR exit('No direct script access allowed');class Workflow_model extends CI_Model{function __construct(){parent::__construct();$this->load->database();}function listing($org,$status,$p,$pp){$this->db->from('workflows')->where(array('organization_id'=>$org,'deleted_at'=>NULL));if($status)$this->db->where('status',strtoupper($status));$n=$this->db->count_all_results();$this->db->where(array('organization_id'=>$org,'deleted_at'=>NULL));if($status)$this->db->where('status',strtoupper($status));$r=$this->db->order_by('updated_at','DESC')->limit($pp,($p-1)*$pp)->get('workflows')->result_array();return array('items'=>array_map(array($this,'view'),$r),'pagination'=>array('page'=>$p,'perPage'=>$pp,'total'=>$n,'totalPages'=>(int)ceil($n/$pp)));}function one($id,$org){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org,'deleted_at'=>NULL))->get('workflows')->row_array();return $r?$this->view($r):NULL;}function save($id,$org,$uid,$d){$now=date('Y-m-d H:i:s');if(!$id){$r=array('id'=>$this->uuid(),'organization_id'=>$org,'workspace_id'=>$d['workspaceId']??NULL,'name'=>$d['name'],'description'=>$d['description']??NULL,'status'=>'DRAFT','nodes'=>json_encode($d['nodes']??array()),'edges'=>json_encode($d['edges']??array()),'settings'=>json_encode($d['settings']??array()),'triggers'=>json_encode($d['triggers']??array(array('type'=>'manual','config'=>array()))),'created_by_id'=>$uid,'runs_count'=>0,'success_count'=>0,'failure_count'=>0,'created_at'=>$now,'updated_at'=>$now);$this->db->insert('workflows',$r);$id=$r['id'];}else{$raw=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('workflows')->row_array();if(!$raw)return NULL;$set=array('updated_at'=>$now);foreach(array('name','description','status') as $f)if(isset($d[$f]))$set[$f]=$f==='status'?strtoupper($d[$f]):$d[$f];foreach(array('nodes','edges','settings','triggers') as $f)if(isset($d[$f]))$set[$f]=json_encode($d[$f]);$this->db->where('id',$id)->update('workflows',$set);}return $this->one($id,$org);}function remove($id,$org){$this->db->where(array('id'=>$id,'organization_id'=>$org))->update('workflows',array('deleted_at'=>date('Y-m-d H:i:s')));return $this->db->affected_rows()>0;}function create_run($wid,$org,$uid,$d){$w=$this->db->where(array('id'=>$wid,'organization_id'=>$org,'deleted_at'=>NULL))->get('workflows')->row_array();if(!$w)return NULL;$now=date('Y-m-d H:i:s');$r=array('id'=>$this->uuid(),'workflow_id'=>$wid,'trigger_type'=>$d['triggerType']??'manual','trigger_data'=>json_encode($d['triggerData']??array()),'status'=>'RUNNING','started_at'=>$now,'input_data'=>json_encode($d['input']??array()),'output_data'=>'{}','node_runs'=>'[]','created_by_id'=>$uid,'created_at'=>$now,'updated_at'=>$now);$this->db->insert('workflow_runs',$r);$this->db->where('id',$wid)->set('runs_count','runs_count+1',FALSE)->update('workflows',array('last_run_at'=>$now));return array('workflow'=>$w,'run'=>$r);}function finish_run($id,$status,$output,$nodes,$error=NULL){$now=date('Y-m-d H:i:s');$this->db->where('id',$id)->update('workflow_runs',array('status'=>$status,'output_data'=>json_encode($output),'node_runs'=>json_encode($nodes),'error'=>$error,'ended_at'=>in_array($status,array('SUCCEEDED','FAILED','CANCELLED'))?$now:NULL,'updated_at'=>$now));$r=$this->db->where('id',$id)->get('workflow_runs')->row_array();if($status==='SUCCEEDED')$this->db->where('id',$r['workflow_id'])->set('success_count','success_count+1',FALSE)->update('workflows');if($status==='FAILED')$this->db->where('id',$r['workflow_id'])->set('failure_count','failure_count+1',FALSE)->update('workflows');return $this->run_view($r);}function runs($org,$wid,$status,$p,$pp){$this->db->from('workflow_runs r')->join('workflows w','w.id=r.workflow_id')->where('w.organization_id',$org);if($wid)$this->db->where('r.workflow_id',$wid);if($status)$this->db->where('r.status',strtoupper($status));$n=$this->db->count_all_results();$this->db->select('r.*')->from('workflow_runs r')->join('workflows w','w.id=r.wor